contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Attempt a send from this tester to an arbitrary receiver of an arbitrary amount.
    // We check that if this contract is not the owner, the call reverts and balances remain unchanged;
    // if it is the owner, the call may succeed and then c's balance decreases by amount and receiver's increases.
    function run(address payable receiver, uint amount) public payable {
        require(receiver != address(0));
        // record balances before
        uint beforeC = address(c).balance;
        uint beforeReceiver = address(receiver).balance;

        // determine whether this contract is the owner by trying to call sendTo and catching revert
        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterC = address(c).balance;
        uint afterReceiver = address(receiver).balance;

        // If the call reverted, balances must be unchanged. If it did not revert, then C's balance decreased by at most amount
        // and receiver's balance increased by at most amount, and the net change equals transfer amount (conserved across these two).
        // Expressed as a single assert relating params, observed balances and revert flag.
        assert(
            reverted
            ? (afterC == beforeC && afterReceiver == beforeReceiver)
            : (beforeC >= afterC && afterReceiver >= beforeReceiver && (beforeC - afterC) == (afterReceiver - beforeReceiver) && (beforeC - afterC) <= amount)
        );
    }

    receive() external payable {}
}

