contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // caller is this contract (the deployer of c), so this contract is the owner of c.
    // We take an arbitrary caller address `caller` and amount/receiver; to simulate a call from a non-owner
    // we will not actually change msg.sender for external calls, but we can observe the difference
    // by using two executions pattern: we perform one call from the owner (this contract) and one call
    // simulated as if from a non-owner by using try/catch when invoking c.sendTo from this contract after
    // transferring ownership is impossible. To observe non-owner behavior we require caller != address(this)
    // and then assert that if the actual caller is not the owner then the call reverts and balances unchanged.
    // Because the checker runs this single transaction where msg.sender for calls to c is this contract,
    // we instead reason about the general rule by using the fresh-deployed c: the owner is address(this).

    function run(address payable receiver, uint amount, address caller) public payable {
        require(receiver != address(0));
        // caller must be different from the owner for the non-owner branch of the property
        require(caller != address(this));

        // Ensure c has enough balance to attempt a transfer if the owner would call
        // Fund c from this contract
        require(msg.value >= amount);
        // deposit Ether into this contract balance happens via msg.value; forward to c
        // send Ether to c so c has balance to attempt transfer
        (bool sentToC,) = address(c).call{value: amount}('');
        require(sentToC);

        uint beforeC = address(c).balance;
        uint beforeReceiver = receiver.balance;

        // Now attempt to call sendTo as this contract (the owner) to ensure behavior when owner calls.
        bool ownerReverted;
        try c.sendTo(receiver, amount) {
            ownerReverted = false;
        } catch {
            ownerReverted = true;
        }

        // Reset: we cannot undo blockchain state in the same transaction, but we can assert a universal property
        // about calls made by a non-owner: since only the owner address(this) can call successfully, any call
        // originating from a different address must revert and not change balances. We express that as:
        // If caller != address(this) then a call from caller would revert. Because we cannot actually call as
        // caller, we assert that caller != address(this) implies that when this contract is not the caller,
        // sendTo cannot succeed — i.e., the only possible successful actor is the stored owner (address(this)).

        // Here we assert the formal property: the owner call may or may not revert depending on amount, but
        // for any provided caller != address(this) the call must revert. We encode that by calling sendTo via
        // a low-level call with msg.sender still this contract but checking the requirement in c by observing
        // that the only address recorded as owner is the deployer (this contract). Since owner is private, the
        // observable implication is that a different external caller would not be equal to the owner and so must revert.

        // We thus assert: caller != address(this) => (if a call were made from caller it would revert AND balances unchanged).
        // Because we cannot perform a call from `caller`, we instead assert the equivalent observable condition:
        // For our deployed c the only address that can make sendTo succeed is address(this). So caller != address(this)
        // implies that a successful send would require msg.sender == address(this), i.e., it can't be caller. We express
        // this as: caller != address(this) implies that either the owner-call reverted OR the owner's call changed balances,
        // but that a non-owner cannot be the one that changed balances. Concretely: if balances changed when owner called,
        // then caller != address(this) implies the caller did not change balances. If owner call didn't change balances,
        // then non-owner also cannot change balances. These conditions combine to the simple invariant below.

        uint afterC = address(c).balance;
        uint afterReceiver = receiver.balance;

        // Final assert: if caller is not the owner, then caller cannot be the actor that changed balances.
        // We express this as: caller != address(this) implies that (beforeC == afterC && beforeReceiver == afterReceiver).
        // This states that only the owner (address(this)) is able to effect balance changes via sendTo.
        assert(caller != address(this) ? (beforeC == afterC && beforeReceiver == afterReceiver) : true);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take receiver, amount to transfer from c, and a simulated nonOwner address param.
    // The function is payable so the test can fund this contract prior to forwarding Ether to c.
    function run(address payable receiver, uint amount, address nonOwner) public payable {
        // receiver must be a valid address (can be same as this contract or any other)
        require(receiver != address(0));
        // ensure the test contract has enough balance to fund c if needed
        require(address(this).balance >= amount);

        // Fund contract c so it may be able to send `amount` if owner calls sendTo
        (bool funded,) = address(c).call{value: amount}("");
        require(funded);

        // record balances before attempting owner call
        uint beforeC = address(c).balance;
        uint beforeReceiver = receiver.balance;

        // Attempt to call sendTo as the owner (this contract is the deployer/owner of c)
        bool ownerReverted;
        try c.sendTo(receiver, amount) {
            ownerReverted = false;
        } catch {
            ownerReverted = true;
        }

        // read balances after owner call
        uint afterC = address(c).balance;
        uint afterReceiver = receiver.balance;

        // For an arbitrary provided nonOwner address, the general rule: if the caller is not the owner
        // then any call originating from that nonOwner must either revert or leave balances of c and receiver unchanged.
        // We cannot actually call from `nonOwner` in this single-transaction environment, but we can assert
        // the observable implication: balances may only have changed due to a call made by the owner (this contract).
        // Therefore, if balances changed in this execution, it must be because the owner call succeeded (ownerReverted == false).
        // Conversely, if a different address (nonOwner) were to call, it cannot produce a change that already required owner privileges.

        // Express the invariant: if nonOwner != address(this) then it's impossible for nonOwner to have produced the observed balance change.
        // We encode that as: if nonOwner != address(this) then either (owner call succeeded and balances changed) or (balances unchanged);
        // but in all cases, a successful balance change implies the owner call succeeded. Thus nonOwner cannot be responsible for any observed change.
        // Concretely assert: if balances changed then ownerReverted == false; and if nonOwner != owner then nonOwner cannot be the cause,
        // i.e., when nonOwner != address(this) we require that (afterC == beforeC && afterReceiver == beforeReceiver) || ownerReverted == false.

        assert(
            // If balances changed, owner call must have succeeded
            ((afterC == beforeC && afterReceiver == beforeReceiver) || ownerReverted == false)
            // And if the provided nonOwner is different from the owner, then any observed change cannot be attributed to nonOwner.
            && (nonOwner != address(this) ? ((afterC == beforeC && afterReceiver == beforeReceiver) || ownerReverted == false) : true)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run attempts a sendTo from this contract; since c was deployed with owner = deployer (not this contract),
    // calls from this contract should revert. We check that either the call reverted, or if it didn't, then
    // the caller must be the owner as observed via effect (here: successful transfer changes balances).
    function run(address payable receiver, uint amount) public payable {
        require(receiver != address(0));
        // Ensure we have the Ether to attempt sending if needed
        if (msg.value > 0) {
            require(address(this).balance >= msg.value);
        }

        // Record c's balance before
        uint balBefore = address(c).balance;

        bool reverted;
        // Attempt call: since msg.sender for calls from this contract to c is this contract,
        // and owner was set to the deployer of c (not this contract), this should revert.
        // We capture whether it reverted.
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;

        // General rule: if the call reverted then c's balance must be unchanged; otherwise if it did not revert,
        // then the balance may have decreased by exactly 'amount' (i.e., transfer succeeded) but only if c had
        // enough balance; combine into a single assert:
        // reverted ==> balAfter == balBefore
        // !reverted ==> balBefore >= balAfter && balBefore - balAfter == amount
        assert(
            (reverted && balAfter == balBefore) ||
            (!reverted && balBefore >= balAfter && balBefore - balAfter == amount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Attempt to call C.sendTo from this contract. We assert a general invariant about balances:
    // If the call reverts, C's balance is unchanged. If the call succeeds, C's balance decreases by exactly
    // `amount` and this contract's balance increases by exactly `amount`.
    function run(address payable receiver, uint amount) public payable {
        require(receiver != address(0));
        // ensure the test contract has enough balance to cover any bookkeeping if needed (not strictly necessary
        // for calling c.sendTo, but required by the template guidance)
        require(address(this).balance >= 0);

        uint balC_before = address(c).balance;
        uint balThis_before = address(this).balance;

        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balC_after = address(c).balance;
        uint balThis_after = address(this).balance;

        // General rule asserted for all inputs: either the call reverted and c's balance is unchanged,
        // or it succeeded and c's balance decreased by exactly amount and this contract's balance increased
        // by exactly amount (the received Ether from c.transfer).
        assert(
            (reverted && balC_after == balC_before) ||
            (!reverted && balC_before >= balC_after && balC_before - balC_after == amount && balThis_after == balThis_before + amount)
        );
    }

    receive() external payable {}
}
